describe('Pinch-to-Zoom on Product Images', () => {
  beforeEach(() => {
    cy.visit('/products/item-123');
  });

  it('should successfully pinch-to-zoom on a product image', () => {
    // Verify product image is visible
    cy.get('[data-testid="product-image"]').should('be.visible');
    cy.get('[data-testid="product-image"]').should('have.attr', 'src');

    // Get initial image dimensions
    cy.get('[data-testid="product-image"]').then(($img) => {
      const initialWidth = $img.width();
      const initialHeight = $img.height();

      // Pinch in (zoom out)
      cy.get('[data-testid="product-image"]').trigger('pinch', {
        clientX: 50,
        clientY: 50,
        scale: 0.5,
        detail: 'pinch-out',
        detailType: 'pinch',
        detailDirection: 'out',
        detailVector: { x: 0, y: 0 },
        detailVectorScale: 1,
        detailVectorUnit: true,
        detailVectorOrigin: { x: 50, y: 50 },
        detailVectorOriginScale: 1,
        detailVectorOriginUnit: true,
        detailVectorOriginDirection: 'out',
        detailVectorOriginType: 'out',
      });

      // Verify zoom out occurred
      cy.get('[data-testid="product-image"]').then(($img) => {
        const zoomedWidth = $img.width();
        const zoomedHeight = $img.height();
        expect(zoomedWidth).to.be.lessThan(initialWidth);
        expect(zoomedHeight).to.be.lessThan(initialHeight);
      });

      // Pinch out (zoom in)
      cy.get('[data-testid="product-image"]').trigger('pinch', {
        clientX: 50,
        clientY: 50,
        scale: 2.0,
        detail: 'pinch-in',
        detailType: 'pinch',
        detailDirection: 'in',
        detailVector: { x: 0, y: 0 },
        detailVectorScale: 1,
        detailVectorUnit: true,
        detailVectorOrigin: { x: 50, y: 50 },
        detailVectorOriginScale: 1,
        detailVectorOriginUnit: true,
        detailVectorOriginDirection: 'in',
        detailVectorOriginType: 'in',
      });

      // Verify zoom in occurred
      cy.get('[data-testid="product-image"]').then(($img) => {
        const zoomedWidth = $img.width();
        const zoomedHeight = $img.height();
        expect(zoomedWidth).to.be.greaterThan(initialWidth);
        expect(zoomedHeight).to.be.greaterThan(initialHeight);
      });
    });
  });

  it('should handle pinch-to-zoom with boundary limits and reset', () => {
    // Verify initial state
    cy.get('[data-testid="product-image"]').should('be.visible');

    // Pinch in (zoom in) to max limit
    cy.get('[data-testid="product-image"]').trigger('pinch', {
      clientX: 50,
      clientY: 50,
      scale: 3.0,
      detail: 'pinch-in',
      detailType: 'pinch',
      detailDirection: 'in',
      detailVector: { x: 0, y: 0 },
      detailVectorScale: 1,
      detailVectorUnit: true,
      detailVectorOrigin: { x: 50, y: 50 },
      detailVectorOriginScale: 1,
      detailVectorOriginUnit: true,
      detailVectorOriginDirection: 'in',
      detailVectorOriginType: 'in',
    });

    // Verify zoom is at max limit (should not exceed 3x)
    cy.get('[data-testid="product-image"]').then(($img) => {
      const currentWidth = $img.width();
      expect(currentWidth).to.be.at.most(3 * 100); // Assuming initial width is 100
    });

    // Attempt to zoom further (should be capped)
    cy.get('[data-testid="product-image"]').trigger('pinch', {
      clientX: 50,
      clientY: 50,
      scale: 5.0,
      detail: 'pinch-in',
      detailType: 'pinch',
      detailDirection: 'in',
      detailVector: { x: 0.1, y: 0.1 },
      detailVectorScale: 1,
      detailVectorUnit: true,
      detailVectorOrigin: { x: 50, y: 50 },
      detailVectorOriginScale: 1,
      detailVectorOriginUnit: true,
      detailVectorOriginDirection: 'in',
      detailVectorOriginType: 'in',
    });

    // Verify zoom remains at max limit
    cy.get('[data-testid="product-image"]').then(($img) => {
      const currentWidth = $img.width();
      expect(currentWidth).to.equal(3 * 100);
    });

    // Pinch out (zoom out) to reset
    cy.get('[data-testid="product-image"]').trigger('pinch', {
      clientX: 50,
      clientY: 50,
      scale: 1.0,
      detail: 'pinch-out',
      detailType: 'pinch',
      detailDirection: 'out',
      detailVector: { x: 0.1, y: 0.1 },
      detailVectorScale: 1,
      detailVectorUnit: true,
      detailVectorOrigin: { x: 50, y: 50 },
      detailVectorOriginScale: 1,
      detailVectorOriginUnit: true,
      detailVectorOriginDirection: 'out',
      detailVectorOriginType: 'out',
    });

    // Verify zoom is reset to initial state
    cy.get('[data-testid="product-image"]').then(($img) => {
      const currentWidth = $img.width();
      expect(currentWidth).to.equal(100);
    });
  });
});
